# (task template, sql template) — {t}=table, {c}=column, {v}=value
SQL_TASKS = [
    ("Senaraikan semua {t}", "SELECT * FROM {t};"),
    ("Kira baris dalam {t}", "SELECT COUNT(*) AS kiraan FROM {t};"),
    ("Cari {t} di mana {c} bersamaan teks", "SELECT * FROM {t} WHERE CAST({c} AS TEXT) = 'Ali';"),
    ("Susun {t} mengikut {c} menurun, 5 teratas", "SELECT * FROM {t} ORDER BY {c} DESC LIMIT 5;"),
    ("Bilangan nilai berbeza {c} dalam {t}", "SELECT COUNT(DISTINCT {c}) AS unik FROM {t};"),
    ("Kemas kini baris id 1 dalam {t}", "UPDATE {t} SET {setc} WHERE id = 1;"),
    ("Padam baris id 9 dari {t}", "DELETE FROM {t} WHERE id = 9;"),
    ("Tambah satu baris ke {t}", "INSERT INTO {t} ({cols}) VALUES ({vals});"),
    ("Purata id mengikut {c2} dalam {t}", "SELECT {c2}, AVG(id) AS purata_id FROM {t} GROUP BY {c2};"),
    ("Nilai id maksimum dalam {t}", "SELECT MAX(id) AS maks FROM {t};"),
    ("Cari {t} dengan {c} mengandungi teks 'a'", "SELECT * FROM {t} WHERE CAST({c} AS TEXT) LIKE '%a%';"),
    ("Kira {t} berkelompok mengikut {c2} yang melebihi 2", "SELECT {c2}, COUNT(*) AS n FROM {t} GROUP BY {c2} HAVING COUNT(*) > 2;"),
    ("Ambil 10 {t} terkini mengikut {c}", "SELECT * FROM {t} ORDER BY {c} DESC LIMIT 10;"),
    ("Jumlah {c} terkecil dan terbesar dalam {t}", "SELECT MIN({c}) AS min, MAX({c}) AS maks FROM {t};"),
    ("Senaraikan {c} unik dalam {t}", "SELECT DISTINCT {c} FROM {t};"),
    ("Cari {t} id antara 1 dan 100", "SELECT * FROM {t} WHERE id BETWEEN 1 AND 100;"),
    ("Cari {t} di mana {c} dalam senarai diberi", "SELECT * FROM {t} WHERE CAST({c} AS TEXT) IN ('Ali', 'Abu');"),
    ("Cari {t} di mana id tiada nilai", "SELECT * FROM {t} WHERE id IS NULL;"),
    ("Kemas kini selamat: tetapkan semula {c2} dalam {t}", "UPDATE {t} SET {c2} = {c2} WHERE id > 0;"),
    ("Padam semua {t} dengan id negatif (pembersihan selamat)", "DELETE FROM {t} WHERE id < 0;"),
    ("Salin {t} ke jadual sandaran", "CREATE TABLE {t}_sandaran AS SELECT * FROM {t};"),
    ("Namakan semula lajur {c} dalam {t}", "ALTER TABLE {t} RENAME COLUMN {c} TO {c}_baru;"),
    ("Tambah lajur nota ke {t}", "ALTER TABLE {t} ADD COLUMN nota TEXT;"),
    ("Buang lajur nota dari {t}", "ALTER TABLE {t} DROP COLUMN nota;"),
    ("Cipta indeks ke atas {c} dalam {t}", "CREATE INDEX idx_{t}_{c} ON {t} ({c});"),
    ("Semak pelan query {t} mengikut id", "EXPLAIN SELECT * FROM {t} WHERE id = 1;"),
    ("Gabung {t} dengan dirinya untuk hierarki", "SELECT a.{c}, b.{c} FROM {t} a JOIN {t} b ON b.{c2} = a.{c};"),
    ("Kira purata id melebihi 5 setiap {c2} dalam {t}", "SELECT {c2}, AVG(id) AS purata FROM {t} GROUP BY {c2} HAVING AVG(id) > 5;"),
    ("Pilih 5 {t} rawak (Postgres)", "SELECT * FROM {t} ORDER BY RANDOM() LIMIT 5;"),
    ("Hadkan {t} kepada halaman kedua (10 sehalaman)", "SELECT * FROM {t} ORDER BY {c} LIMIT 10 OFFSET 10;"),
    ("Tukar {c} jadi teks dalam {t}", "SELECT CAST({c} AS TEXT) AS teks FROM {t};"),
    ("Panjang teks {c} dalam {t}", "SELECT {c}, LENGTH(CAST({c} AS TEXT)) AS panjang FROM {t};"),
    ("Gabung dua teks {c} dan {c2} dalam {t}", "SELECT CAST({c} AS TEXT) || ' ' || CAST({c2} AS TEXT) AS penuh FROM {t};"),
    ("Tarikh hari ini dalam SQL", "SELECT CURRENT_DATE;"),
    ("Kira {t} yang id tidak kosong", "SELECT COUNT(*) AS kiraan FROM {t} WHERE id IS NOT NULL;"),
    ("Kedudukan {t} mengikut {c} menurun", "SELECT {c}, ROW_NUMBER() OVER (ORDER BY {c} DESC) AS ranking FROM {t};"),
    ("Jumlah terkumpul {c} dalam {t}", "SELECT id, COUNT(*) OVER (ORDER BY id) AS terkumpul FROM {t};"),
    ("Baris sebelumnya untuk setiap {t}", "SELECT {c}, LAG({c}) OVER (ORDER BY id) AS sebelum FROM {t};"),
    ("Pendua {c} dalam {t}", "SELECT {c}, COUNT(*) AS n FROM {t} GROUP BY {c} HAVING COUNT(*) > 1;"),
    ("Peratusan setiap {c2} dalam {t}", "SELECT {c2}, COUNT(*) * 100.0 / SUM(COUNT(*)) OVER () AS pct FROM {t} GROUP BY {c2};"),
    ("3 {t} teratas setiap {c2}", "SELECT * FROM (SELECT t.*, ROW_NUMBER() OVER (PARTITION BY {c2} ORDER BY id) AS rn FROM {t} t) s WHERE rn <= 3;"),
    ("{t} tanpa padanan (anti-join)", "SELECT * FROM {t} a LEFT JOIN {t} b ON b.{c2} = a.{c} WHERE b.{c} IS NULL;"),
    ("Wujudkan {c} jika tiada dalam {t}", "INSERT INTO {t} ({c}) SELECT 'baru' WHERE NOT EXISTS (SELECT 1 FROM {t} WHERE {c} = 'baru');"),
    ("Naikkan semua id {t} (contoh kemas kini pukal selamat)", "UPDATE {t} SET {c2} = {c2} WHERE id > 0;"),
    ("Padam pendua {t} kekalkan id terkecil", "DELETE FROM {t} WHERE id NOT IN (SELECT MIN(id) FROM {t} GROUP BY {c});"),
    ("Ringkas {t} ke jadual laporan", "CREATE TABLE laporan_{t} AS SELECT {c2}, COUNT(*) AS n FROM {t} GROUP BY {c2};"),
    ("Band {t} ikut julat id", "SELECT CASE WHEN id < 10 THEN 'rendah' WHEN id < 100 THEN 'sederhana' ELSE 'tinggi' END AS band, COUNT(*) FROM {t} GROUP BY 1;"),
    ("Nilai {c} paling kerap dalam {t}", "SELECT {c}, COUNT(*) AS n FROM {t} GROUP BY {c} ORDER BY n DESC LIMIT 1;"),
    ("Kaitkan {t} dengan dirinya (pasangan id berbeza)", "SELECT a.id, b.{c} FROM {t} a JOIN {t} b ON b.id <> a.id LIMIT 10;"),
    ("Baris berikutnya {c} dalam {t} (LEAD)", "SELECT {c}, LEAD({c}) OVER (ORDER BY id) AS berikut FROM {t};"),
    ("Kuartil {c} dalam {t} (NTILE 4)", "SELECT {c}, NTILE(4) OVER (ORDER BY {c}) AS kuartil FROM {t};"),
    ("Kedudukan padat {c} dalam {t} (DENSE_RANK)", "SELECT {c}, DENSE_RANK() OVER (ORDER BY {c} DESC) AS rank_padat FROM {t};"),
    ("{t} yang ada kembar {c2} (EXISTS)", "SELECT * FROM {t} a WHERE EXISTS (SELECT 1 FROM {t} b WHERE b.{c2} = a.{c2} AND b.id <> a.id);"),
    ("{c} dalam senarai subquery {t}", "SELECT * FROM {t} WHERE {c} IN (SELECT {c} FROM {t} WHERE id > 0);"),
    ("Purata bergerak id dalam {t}", "SELECT id, AVG(id) OVER (ORDER BY id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS purata_bergerak FROM {t};"),
    ("Jumlah kumulatif id setiap {c2} dalam {t}", "SELECT {c2}, id, SUM(id) OVER (PARTITION BY {c2} ORDER BY id) AS kumulatif FROM {t};"),
]

# Konsep SQL mengikut turutan tutorial (asas -> lanjutan). Ditulis semula secara
# ringkas dalam gaya repo (campuran Melayu/English), bukan salinan mana-mana teks.
# Setiap baris ditambah terus sekali (tanpa gandaan frasa) supaya soalan konsep
# kekal semula jadi. Semua contoh guna jadual generik kedai (pelanggan/pesanan).
SQL_CONCEPTS = [
    ("Apa itu SQL?", "SQL (Structured Query Language) ialah bahasa piawai untuk berurusan dengan pangkalan data hubungan: cipta, baca, kemas kini dan padam data dalam jadual."),
    ("Lima kumpulan perintah SQL?", "DDL (cipta/ubah struktur: CREATE, ALTER, DROP), DQL (tanya: SELECT), DML (ubah data: INSERT, UPDATE, DELETE), DCL (kebenaran: GRANT, REVOKE), TCL (transaksi: BEGIN, COMMIT, ROLLBACK)."),
    ("Jenis data SQL yang biasa?", "Teks: VARCHAR(n)/TEXT; nombor: INT, DECIMAL(p,s); tarikh: DATE, TIMESTAMP; boolean: BOOLEAN; binari: BYTEA/BLOB. Pilih yang paling sempit yang muat data anda."),
    ("Apa itu NULL dalam SQL?", "NULL bermaksud nilai tiada/tidak diketahui — bukan sifar, bukan rentetan kosong. Perbandingan `= NULL` tidak pernah benar; guna `IS NULL` / `IS NOT NULL`."),
    ("Komen dalam SQL?", "Guna `--` untuk sebaris dan `/* ... */` untuk berbilang baris. Komen terangkan niat query yang tidak jelas, bukan ulangi kod."),
    ("Wildcard dalam LIKE?", "`%` padan sifar atau lebih aksara, `_` padan tepat satu aksara. Contoh: `WHERE nama LIKE 'A%'` cari nama bermula A."),
    ("Perbezaan DELETE, TRUNCATE dan DROP?", "DELETE padam baris (boleh WHERE, boleh rollback dalam transaksi, perlahan). TRUNCATE kosongkan jadual serta-merta (tiada WHERE, reset auto-increment). DROP buang jadual/struktur seluruhnya."),
    ("Cipta dan pilih database?", "Cipta: `CREATE DATABASE kedai;`. Guna: `USE kedai;` (MySQL) atau sambung terus ke DB itu (Postgres: `\\c kedai`). Padam: `DROP DATABASE kedai_lama;` — tiada undur."),
    ("Tukar nama database?", "MySQL tiada RENAME DATABASE selamat — cipta DB baharu, pindah jadual dengan `RENAME TABLE lama.t TO baru.t`, sahkan, kemudian DROP yang lama."),
    ("Peraturan reka jadual yang baik?", "Satu tujuan satu jadual, setiap baris ada primary key, tiada data berulang (rujuk, jangan salin), jenis data tepat, NOT NULL pada lajur wajib."),
    ("Salin struktur atau data jadual?", "Struktur + data: `CREATE TABLE baru AS SELECT * FROM lama;`. Struktur sahaja: tambah `WHERE 1 = 0`. Data sahaja: `INSERT INTO sedia_ada SELECT * FROM lama;`."),
    ("Jadual sementara (TEMP)?", "`CREATE TEMP TABLE sesi AS SELECT ...` hidup selagi sambungan dibuka, ghaib bila tutup. Sesuai untuk langkah perantaraan laporan — jangan simpan data kekal di situ."),
    ("AUTO_INCREMENT vs SEQUENCE?", "AUTO_INCREMENT (MySQL) keluarkan id automatik setiap INSERT. SEQUENCE (Postgres: `GENERATED ... AS IDENTITY`) objek bebas yang boleh dikongsi beberapa jadual dan ditetapkan semula."),
    ("INSERT banyak baris sekaligus?", "Satu kenyataan, banyak tuple — jauh lebih laju dari INSERT berulang:\n```sql\nINSERT INTO pengguna (nama) VALUES ('Ali'), ('Abu'), ('Siti');\n```"),
    ("Padam baris pendua, kekalkan satu?", "Kenal pasti kunci pendua, padam yang id besar:\n```sql\nDELETE FROM pengguna a USING pengguna b WHERE a.id > b.id AND a.emel = b.emel;\n```"),
    ("Bahaya SQL dinamik?", "Jangan gabung input pengguna ke dalam string SQL (`'... ' + nama + ' ...'`) — itu lubang SQL injection. Guna parameter terikat (`$1`, `?`, `%s`) supaya input dianggap data, bukan kod."),
    ("CTE (WITH) untuk apa?", "WITH namakan subquery sebagai langkah boleh baca (`WITH aktif AS (...) SELECT ...`), boleh rujuk berulang, dan asas kepada query rekursif. Gantikan subquery bersarang yang dalam."),
    ("TOP, LIMIT, FETCH FIRST?", "Semua hadkan baris: SQL Server `SELECT TOP 10 ...`, MySQL/Postgres `... LIMIT 10`, piawai `... FETCH FIRST 10 ROWS ONLY`. Sentiasa pasang ORDER BY supaya had itu menentukan."),
    ("Pagination yang betul?", "OFFSET melangkau makin perlahan bila halaman jauh. Keyset lebih laju: ingat id terakhir, tanya `WHERE id > 100 ORDER BY id LIMIT 10`. Guna OFFSET hanya untuk halaman kecil."),
    ("Alias lajur dan jadual?", "Beri nama pendek: `SELECT p.nama AS pelanggan FROM pengguna AS p;`. AS pilihan untuk jadual, wajib jelas untuk lajur kiraan supaya aplikasi baca hasil dengan betul."),
    ("DISTINCT vs GROUP BY?", "DISTINCT buang baris kembar selepas SELECT. GROUP BY kumpulkan baris untuk agregat (COUNT/SUM/AVG). Elak `SELECT DISTINCT` sebagai penampal join yang kembar — betulkan join."),
    ("WHERE vs HAVING?", "WHERE tapis baris SEBELUM kumpul (guna indeks). HAVING tapis KUMPULAN selepas GROUP BY (cth. `HAVING COUNT(*) > 5`). Syarat agregat tidak boleh duduk dalam WHERE."),
    ("Corak LIKE yang biasa?", "`'A%'` bermula A, `'%@x.my'` tamat domain, `'%botol%'` mengandungi, `'A_c'` A + satu aksara + c. LIKE bermula `%` tidak boleh guna indeks biasa — perlahan pada jadual besar."),
    ("IN vs EXISTS?", "IN banding dengan senarai nilai (senang dibaca, perlahan bila subquery besar). EXISTS berhenti sebaik jumpa padanan pertama — lazimnya lebih laju untuk semak kewujudan."),
    ("BETWEEN termasuk hujung?", "Ya, `BETWEEN 1 AND 10` termasuk 1 dan 10. Untuk tarikh, elak `BETWEEN '2026-01-01' AND '2026-01-31'` (terlepas masa 31hb); guna `>= awal AND < bulan_berikut`."),
    ("UNION vs UNION ALL?", "UNION gabungkan hasil DAN buang kembar (perlu sort, perlahan). UNION ALL gabung sahaja (laju). Mesti sama bilangan dan jenis lajur sepadan."),
    ("EXCEPT dan INTERSECT?", "EXCEPT pulangkan baris dalam query pertama tiada dalam kedua. INTERSECT pulangkan yang ada dalam kedua-dua. Guna untuk beza set dan persamaan set tanpa join rumit."),
    ("ALL dan ANY?", "`> ALL (...)` mesti lebih besar dari SEMUA nilai; `> ANY (...)` cukup lebih besar dari SATU. Lazimnya EXISTS/JOIN lebih jelas — simpan untuk perbandingan ambang."),
    ("Perangkap NOT + NULL?", "`WHERE status NOT IN ('aktif', NULL)` tidak pulangkan apa-apa kerana perbandingan dengan NULL hasilnya UNKNOWN. Buang NULL dari senarai dahulu atau tambah `OR status IS NULL`."),
    ("CASE asas?", "IF dalam query: `SELECT nama, CASE WHEN stok = 0 THEN 'habis' WHEN stok < 10 THEN 'rendah' ELSE 'ok' END AS status FROM produk;`."),
    ("Fungsi UPPER, LOWER, TRIM?", "`UPPER('ali')` -> 'ALI', `LOWER('Ali')` -> 'ali', `TRIM('  ali  ')` -> 'ali'. Normalkan input sebelum banding supaya 'Ali' sama dengan 'ali '."),
    ("LENGTH, SUBSTRING, CONCAT?", "`LENGTH(nama)` panjang teks, `SUBSTRING(nama, 1, 3)` tiga aksara pertama, `nama || '!'` (Postgres) atau `CONCAT(nama, '!')` cantum. Indeks bermula 1, bukan 0."),
    ("ROUND, CEIL, FLOOR, MOD?", "`ROUND(2.675, 2)` bundar perpuluhan, `CEIL`/`FLOOR` ke atas/bawah, `MOD(7, 3)` baki 1. Kira wang dalam sen (integer), bukan float."),
    ("Fungsi tarikh yang penting?", "`CURRENT_DATE` hari ini, `NOW()` cap masa kini, `tarikh + INTERVAL '7 days'` tambah tempoh, `EXTRACT(YEAR FROM tarikh)` ambil tahun. Simpan UTC, papar ikut zon pengguna."),
    ("COALESCE dan NULLIF?", "`COALESCE(a, b, 'tiada')` pulangkan bukan-null pertama (nilai lalai paparan). `NULLIF(a, b)` pulangkan NULL bila sama (elak bahagi sifar: `x / NULLIF(y, 0)`)."),
    ("CAST dan CONVERT?", "Tukar jenis: `CAST(harga AS TEXT)`, Postgres `harga::TEXT`, MySQL `CONVERT(harga, CHAR)`. CAST gagal (error) lebih baik dari senyap salah — tangkap ralatnya."),
    ("Fungsi agregat asas?", "COUNT(*) kira baris, COUNT(lajur) langkau NULL, SUM/AVG/MIN/MAX ringkaskan. Agregat tanpa GROUP BY pulangkan satu baris untuk seluruh jadual."),
    ("Kira nilai berbeza?", "`SELECT COUNT(DISTINCT bandar) FROM pelanggan;`. Untuk senarai pula: Postgres `STRING_AGG(nama, ', ')`, MySQL `GROUP_CONCAT(nama)`, SQL Server `STRING_AGG`."),
    ("JSON dalam SQL moden?", "Simpan separa-struktur dalam JSONB (Postgres) / JSON (MySQL). Tanya: Postgres `data->>'nama'`, MySQL `JSON_EXTRACT(data, '$.nama')`. Indeks lajur janaan untuk carian laju, bukan imbasan penuh."),
    ("Regex dalam SQL?", "Postgres `WHERE emel ~ '^[A-Za-z0+9._%+-]+@x\\.my$'`, MySQL `REGEXP_LIKE(emel, '^...$')`. Regex kuat tapi perlahan — sahkan format di aplikasi, bukan setiap query."),
    ("Primary key vs unique?", "Primary key: unik + tidak null + satu sahaja sejadual (pengenalan baris). Unique: unik tapi boleh banyak dan benarkan NULL (satu NULL sahaja dalam kebanyakan DB)."),
    ("Foreign key dan ON DELETE?", "Foreign key pastikan nilai wujud di jadual induk. `ON DELETE CASCADE` padam anak automatik (bahaya tapi kemas), `RESTRICT` halang, `SET NULL` putuskan pautan. Sentiasa indeks lajur anak."),
    ("CHECK dan DEFAULT?", "`CHECK (harga >= 0)` tolak data mustahil di pintu DB. `DEFAULT 0`/`DEFAULT CURRENT_TIMESTAMP` isi nilai bila INSERT tidak beri. Peraturan di DB kekal walau aplikasi bertukar."),
    ("Composite key bila?", "Kunci primer berbilang lajur (`PRIMARY KEY (pesanan_id, produk_id)`) untuk jadual pautan many-to-many. Tertib lajur ikut corak query lazim supaya indeks berguna."),
    ("LEFT JOIN vs RIGHT JOIN?", "LEFT kekalkan SEMUA baris kiri (padanan tiada jadi NULL). RIGHT songsangkan. Tulis semula RIGHT sebagai LEFT (tukar tertib jadual) supaya semua query dibaca satu arah."),
    ("FULL OUTER JOIN bila?", "Bila mahu semua dari kedua-dua sisi (padanan + yatim kiri + yatim kanan). MySQL tiada sintaks ini — gabung LEFT + RIGHT dengan UNION."),
    ("CROSS JOIN untuk apa?", "Setiap baris A ganding setiap baris B (hasil darab). Sengaja untuk matriks/pilihan (saiz × warna), atau jadual nombor. Tanpa sedar ia letupan baris — semak kiraan dahulu."),
    ("SELF JOIN contoh?", "Jadual rujuk dirinya: pekerja-penyelia (`JOIN pekerja p ON p.penyelia_id = e.id`), kategori induk-anak. Alias berbeza (a/b) wajib supaya DB bezakan dua peranan."),
    ("UPDATE atau DELETE dengan JOIN?", "Kemas kini/padam berpandu jadual lain: `UPDATE stok s JOIN senarai_hitam b ON b.id = s.id SET s.aktif = 0;`. Uji sebagai SELECT dahulu, kemudian tukar kata kerja — elak padam salah sasaran."),
    ("Query rekursif (CTE)?", "Untuk hierarki (kategori, carta org): `WITH RECURSIVE r AS (SELECT ... asas UNION ALL SELECT ... FROM r JOIN ...) SELECT * FROM r;`. Hadkan kedalaman supaya tidak gelung infiniti."),
    ("Kenapa guna VIEW?", "VIEW simpan query kompleks sebagai jadual maya (`CREATE VIEW jualan_bulanan AS ...`). Ringkaskan capaian, sorok lajur sensitif, dan tukar logik tanpa sentuh aplikasi."),
    ("Batasan view boleh-kemas-kini?", "View ringkas (satu jadual, tiada GROUP BY/DISTINCT) boleh INSERT/UPDATE terus. View agregat/join baca-sahaja — kemas kini jadual asas atau guna peraturan/TRIGGER ganti."),
    ("Bila indeks membantu?", "Indeks lajukan WHERE/JOIN/ORDER BY pada lajur ditanya. Setiap indeks perlahan INSERT/UPDATE dan makan storan — indeks lajur yang ditanya, bukan semua lajur."),
    ("Tertib lajur indeks komposit?", "Susun ikut query: kesamaan dahulu (`bandar`), kemudian julat/susun (`tarikh`). `INDEX (bandar, tarikh)` layan `WHERE bandar=X ORDER BY tarikh`, songsangnya tidak."),
    ("UNIQUE INDEX vs CONSTRAINT?", "Sama kesan (keunikan dikuatkuasa + carian laju). Constraint namakan peraturan perniagaan (`UNIQUE (emel)`); indeks cipta manual untuk prestasi separa (`WHERE aktif`) tanpa peraturan."),
    ("SHOW dan DROP INDEX?", "Semak: MySQL `SHOW INDEX FROM pesanan;`, Postgres `\\d pesanan`. Buang yang tidak diguna (ukur dulu dengan EXPLAIN): `DROP INDEX idx_lama ON pesanan;`."),
    ("Clustered vs non-clustered?", "Clustered susun data fizikal ikut kunci (satu sejadual, lazimnya primary key) — julat id laju. Non-clustered struktur asing menuding ke baris — banyak dibenarkan, sedikit overhed tulis."),
    ("Subquery skalar?", "Subquery pulangkan satu nilai: `SELECT nama, (SELECT COUNT(*) FROM pesanan o WHERE o.pengguna_id = p.id) AS bilangan FROM pengguna p;`. Perlahan baris-demi-baris — JOIN/GROUP BY selalunya lebih laju."),
    ("Correlated subquery?", "Subquery rujuk lajur luar (`WHERE o.pengguna_id = p.id`) lalu dinilai setiap baris luar. Betul hasilnya, mahal kosnya — tulis semula sebagai JOIN bila boleh."),
    ("EXISTS vs IN untuk subquery?", "EXISTS berhenti awal (laju, selamat dengan NULL). IN bina set penuh dahulu (senang dibaca, semak NULL). Pilih EXISTS untuk kewujudan, IN untuk senarai kecil yang pasti."),
    ("ACID itu apa?", "Atomicity (semua-atau-tiada), Consistency (peraturan kekal), Isolation (transaksi serentak tidak kacau), Durability (commit kekal walau blackout). Kontrak asas transaksi."),
    ("Transaksi selamat?", "Bungkus kerja berkaitan: `BEGIN; UPDATE akaun SET baki = baki - 100 WHERE id = 1; UPDATE akaun SET baki = baki + 100 WHERE id = 2; COMMIT;`. Ralat di tengah → ROLLBACK, jangan separa."),
    ("Stored procedure bila?", "Bungkus logik multi-langkah di sisi DB (`CREATE PROCEDURE tutup_bulan() ... CALL tutup_bulan();`) untuk aturan yang mesti sama walau aplikasi berganti. Jangan sumbat logik bisnes seluruhnya — susah uji dan version."),
    ("Trigger: guna dan awas?", "Trigger laksana automatik selepas INSERT/UPDATE (audit log, cap masa). Bahaya: logik tersembunyi (sukar debug), gelung berantai, perlahan pukal. Audit sahaja; peraturan bisnes kekal di aplikasi."),
    ("Window function vs GROUP BY?", "GROUP BY runtuhkan baris jadi satu sebaris kumpulan. Window (ROW_NUMBER, RANK, SUM OVER) kira tanpa runtuh — setiap baris kekal dengan nilai kumpulannya. Pilih ikut bentuk output mahu."),
    ("Cursor: kenapa elak?", "Cursor proses baris demi baris (perlahan, kunci lama). 99% kes boleh tulis semula set-based (JOIN/window). Cursor hanya untuk prosedur baris yang tiada jalan set."),
    ("PIVOT dengan CASE?", "Putar baris jadi lajur: `SELECT bandar, SUM(CASE WHEN tahun=2025 THEN jumlah END) AS y2025, SUM(CASE WHEN tahun=2026 THEN jumlah END) AS y2026 FROM jualan GROUP BY bandar;`."),
    ("Asas tuning query?", "Urut: 1) EXPLAIN cari imbasan penuh, 2) indeks lajur WHERE/JOIN/ORDER, 3) elak SELECT * dan fungsi atas lajur berindeks, 4) ukur semula. Ulang sehingga cukup laju — tekaan tanpa EXPLAIN itu khayalan."),
    ("Backup pangkalan data?", "Jadualkan: Postgres `pg_dump kedai | gzip > sandar.sql.gz`, MySQL `mysqldump --single-transaction`. Simpan luar mesin, uji restore berkala — backup yang tidak pernah di-restore itu angan-angan."),
    ("Susunan klausa SELECT yang betul?", "Tulis ikut tertib: SELECT → FROM → JOIN → WHERE → GROUP BY → HAVING → ORDER BY → LIMIT. Enjin menilai FROM dahulu (sebab itu alias SELECT tidak boleh dipakai dalam WHERE)."),
    ("COUNT(*) vs COUNT(lajur)?", "COUNT(*) kira semua baris termasuk NULL. COUNT(emel) langkau NULL. Untuk 'berapa ada emel', guna yang kedua; untuk saiz jadual, yang pertama."),
    ("Kenapa elak SELECT *?", "Rapuh (lajur baharu pecahkan aplikasi), boros (tarik BLOB tidak perlu), perlahan (batal covering index). Senarai lajur eksplisit — kod yang tahan masa."),
    ("Konvensyen nama yang kemas?", "Jadual jamak kecil (`pengguna`), lajur snake_case (`pengguna_id`), primary key `id`, foreign key `jadual_id`, indeks `idx_jadual_lajur`. Konsisten > cantik."),
    ("Normalisasi ringkas?", "1NF: nilai atom (tiada senarai dalam sel). 2NF: tiada separa-bergantung pada sebahagian kunci. 3NF: tiada transitif (bandar pengguna ikut poskod, bukan nama). Normalkan dahulu, denormalisasi bila ukur perlahan."),
    ("SQL injection dalam satu ayat?", "Jangan bina SQL dari rentetan + input pengguna; guna parameter terikat dan keistimewaan DB paling minimum untuk akaun aplikasi."),
    ("Isolation level bila risau?", "Bacaan serentak nampak data separuh-tulis (dirty/phantom). Kewangan dan stok perlukan tahap ketat + kunci baris (`SELECT ... FOR UPDATE`); laporan boleh longgar. Uji di bawah beban sebenar."),
    ("Panduan cepat mula query?", "1) Senarai lajur perlu, 2) FROM + JOIN betul, 3) WHERE tapis, 4) GROUP/HAVING jika agregat, 5) ORDER + LIMIT, 6) EXPLAIN sebelum ke produksi."),
]

SQL_ADV = [
    ("EXCEPT vs INTERSECT vs MINUS", "`EXCEPT` (tolak set, standard!), `INTERSECT` (kekalkan persamaan), Oracle `MINUS` (EXCEPT lama!); `EXCEPT ALL` kekalkan duplikat — operasi set menegak (lajur sepadan!), dedupes lalai kecuali ALL."),
    ("VALUES table constructor", "`VALUES (1,'a'), (2,'b')` membina jadual sebaris (`FROM (VALUES ...) AS t(id,nama)`); `TABLE t` pintasan SELECT * — data ujian sebaris (tanpa jadual sebenar!), CTE gabung (`WITH v AS (...)`)."),
    ("TABLESAMPLE sampling", "`TABLESAMPLE BERNOULLI(10)` rawak per-baris (~10%!), `SYSTEM (1000)` blok pantas (berat sebelah berkelompok!) — sampel QA (bukan anggaran tepat!), kaedah didokumen (keputusan dilabel anggaran!)."),
    ("GROUPING SETS CUBE ROLLUP", "`GROUP BY GROUPING SETS ((a),(a,b),())` kubus tersuai; `ROLLUP(a,b)` hierarki subtotal; `CUBE(a,b)` semua kombinasi; `GROUPING()` label aras — agregat multi-aras satu laluan (bukan UNION manual!), NULL dikelirukan (GROUPING bezakan!)."),
    ("QUALIFY filter windows", "Snowflake/DuckDB `QUALIFY ROW_NUMBER() ... = 1` tapis hasil window (tanpa subquery!); standard: subquery + WHERE — QUALIFY di mana disokong (bacaan bersih!), subquery portabel (semua enjin!)."),
    ("window frame ROWS RANGE", "`ROWS BETWEEN 6 PRECEDING AND CURRENT ROW` fizikal (purata bergerak 7-hari!), `RANGE` rakan-nilai (seri berkongsi!), `GROUPS` rakan-kumpulan; `UNBOUNDED PRECEDING` kumulatif — frame eksplisit (lalai `RANGE UNBOUNDED` menipu!), unit difahami."),
    ("window LEAD LAG IGNORE", "`LAG(x) IGNORE NULLS` langkau tiada (siri masa berlubang!); `LEAD(x, 2)` pandang 2 ke depan; `NTH_VALUE(x, 3)` kedudukan; `NTILE(4)` kuartil; `CUME_DIST/PERCENT_RANK` taburan — NULL dilayan (IGNORE vs RESPECT!), bingkai ditetapkan."),
    ("window FILTER PARTITION", "`COUNT(*) FILTER (WHERE aktif) OVER (PARTITION BY bandar)` agregat bersyarat per tetingkap (tanpa CASE!); `PARTITION BY` berbilang lajur; NULL partition berkumpul (dijangka!) — FILTER elegan (CASE verbose!), partition direka (bukan rawak!)."),
    ("LATERAL join function", "`JOIN LATERAL (SELECT ... WHERE x.id = t.id LIMIT 3)` korelasi per baris (top-N setiap kumpulan!); SQL Server `CROSS/OUTER APPLY` setara — LATERAL untuk per-baris subquery (N kecil!), pra-agregat untuk besar (skala!)."),
    ("PIVOT UNPIVOT dynamic", "`PIVOT (SUM(jumlah) FOR suku IN ('Q1','Q2'))` baris-ke-lajur; `UNPIVOT` songsang; dinamik perlukan SQL dinamik (senarai lajur dibina!) — PIVOT untuk laporan tetap (lajur diketahui!), app pivot untuk dinamik (fleksibiliti!)."),
    ("MERGE upsert matched", "`MERGE INTO sasaran USING sumber ON ... WHEN MATCHED THEN UPDATE ... WHEN NOT MATCHED THEN INSERT ... WHEN NOT MATCHED BY SOURCE THEN DELETE` segerak penuh atom (ETL perlahan-berubah!); syarat tambahan (`AND`) cabang halus — MERGE atom (bukan baca-tulis-berlumba!), diuji per cabang (matched/unmatched/both!)."),
    ("RETURNING OUTPUT clause", "Postgres `RETURNING id` (ID segar tanpa round-trip!); SQL Server `OUTPUT inserted.id` setara; MySQL tiada (`LAST_INSERT_ID()` ganti!) — ID dibaca dari kenyataan sama (bukan query kedua berlumba!), dialek diketahui."),
    ("TOP FETCH pagination", "T-SQL `TOP 10` / `OFFSET 20 ROWS FETCH NEXT 10 ROWS ONLY` (standard!); MySQL `LIMIT 10, 20` (offset-dalam untuk jutaan! keyset ganti!); Oracle `FETCH FIRST` — halaman dengan ORDER stabil (tanpa ORDER rawak!), keyset skala (offset tidak!)."),
    ("JSON query modify", "`JSON_VALUE(doc,'$.nama')` ekstrak, `JSON_QUERY` objek, `JSON_MODIFY(doc,'$.umur',30)` kemas kini (SQL Server!); `ISJSON()` kekang; indeks pada laluan lazim — JSON untuk fleksibel (bukan ganti lajur disoal!), diindeks bila panas."),
    ("generated virtual stored", "`harga_cukai DECIMAL GENERATED ALWAYS AS (harga*1.1) STORED` dikira+konsisten (indeks boleh!); VIRTUAL kira-semasa-baca (jimat stor!); MySQL/Postgres sintaks berbeza sedikit — terbitan dijamin (bukan app hitung!), STORED untuk indeks."),
    ("temporal system tables", "`PERIOD FOR SYSTEM_TIME` + `WITH SYSTEM VERSIONING` simpan sejarah baris automatik (`FOR SYSTEM_TIME AS OF` tanya masa lalu!); retention (`HISTORY_RETENTION`) — audit tanpa trigger (enjin uruskan!), purata kos stor (dasar jelas!)."),
    ("graph node edge match", "`CREATE TABLE Orang AS NODE` + `Suka AS EDGE`; `MATCH (a:Orang)-[Suka]->(b)` lalui rangkaian (rakan-rakan-rakan!); `SHORTEST_PATH` laluan — graf dalam SQL (rangkaian sosial!), khusus graf DB untuk dalam (Neo4j!)."),
    ("spatial index nearest", "`CREATE SPATIAL INDEX` + `ST_Distance_Sphere(p1,p2)` meter + `ST_Contains(geom, point)` dalam-kawasan; SRID sepadan (4326 GPS!) — unit difahami (darjah vs meter!), indeks spatial (imbasan penuh dibunuh!)."),
    ("columnstore archive analytics", "Columnstore (SQL Server: `CLUSTERED COLUMNSTORE INDEX`) mampat 10x + imbas lajur (analitik!); archive tables + `COLUMNSTORE_ARCHIVE` sejuk — OLTP baris (transaksi!), analitik kolumnar (imbasan!), pilihan mengikut beban."),
    ("memory optimized table", "`MEMORY_OPTIMIZED` + `DURABILITY=SCHEMA_ONLY` (sementara pantas!) / `SCHEMA_AND_DATA` (kekal!); hash indexes (`BUCKET_COUNT` betul!); natively compiled procs — memori untuk panas melampau (had RAM!), kekal disemak (hilang = bencana!)."),
    ("always encrypted enclave", "Always Encrypted (kolum sulit, kunci di luar DB!) + enklave VBS (pengiraan atas sulit!) — DBA tidak nampak plaintext (pematuhan!); driver khas (bukan semua pemacu sokong!) — sulit hujung-ke-hujung (aplikasi sahaja pegang kunci!)."),
    ("dynamic masking rls azure", "`MASKED WITH (FUNCTION='email()')` topeng per-peranan (panggilan pusat nampak XXX!); RLS `FILTER PREDICATE` baris per pengguna — topeng paparan (bukan keselamatan penuh!), RLS baris (multi-tenant!), audit gabung."),
    ("ssis package deploy", "SSIS (`.dtsx`, aliran data/kawalan) deploy ke SSISDB (`catalog.deploy_project`); parameter persekitaran (dev/prod!); execution reports — ETL visual (jejak audit!), pakej berversi (git!), jadual ejen (bukan manual!)."),
    ("ssrs report paginated", "SSRS `.rdl` laporan berpaginasi (jadual/matrik/carta!) + langganan (emel berjadual!) + parameter cascading — laporan operasi (cetak/PDF!), bukan dasbor interaktif (Power BI untuk itu!)."),
    ("powerbi directquery vs import", "Import (mampat xColumnar, pantas, refresh berjadual!) vs DirectQuery (langsung, sentiasa segar, perlahan!) vs Direct Lake — mod dipilih per data (saiz/kesegaran!), agregasi tabulasi (`SUMX` iterator!), DAX measured (bukan lajur dikira untuk agregat!)."),
    ("delta lake merge vacuum", "`MERGE INTO` upsert lakehouse + `VACUUM` (retensi 7 hari! time-travel selamat!) + `OPTIMIZE ZORDER` (laju!); Bronze→Silver→Gold medallion — lakehouse berversi (perjalanan masa!), vakum dijadual (storan terkawal!)."),
    ("iceberg snapshot expire", "`CALL system.expire_snapshots(table, older_than)` potong sejarah; `rewrite_data_files` padatkan; partition evolution (skema berubah selamat!) — snapshot diurus (storan!), evolusi tanpa tulis semula (migrasi sifar-downtime!)."),
    ("dbt ref test source", "`{{ ref('pesanan') }}` graf pergantungan (tertib bina automatik!); `source()` mentah didokumen; `unique`+`not_null` tests setiap model (CI gagal bila pecah!); `snapshot` SCD2 sejarah — transformasi diuji (bukan harapan!), docs dijana (lineage!)."),
    ("trino cost connectors", "Trino/Presto federasi (hive/postgres/kafka/delta dalam satu query!); connector pushdown disemak (`EXPLAIN`!); exchange spill cakera (tanya gergasi!) — federasi untuk gabungan (bukan pindah!), pushdown disahkan (tarik penuh = perlahan!)."),
    ("snowflake clustering mpc", "`CLUSTER BY (tarikh)` mikro-partition prune (bukan indeks!); `AUTOMATIC_CLUSTERING` latar; `MPC` kongsi selamat (tiada salinan!) — kluster ikut turas (prune!), saiz gudang ikut beban (auto-gantung!), kos dipantau (kredit!)."),
    ("bigquery partition expire", "`PARTITION BY DATE(dibuat)` + `partition_expiration_days` + `require_partition_filter` (imbasan penuh ditolak!) — partition wajib (kos!), luput automatik (storan terkawal!), slot ditempah beban stabil (atas permintaan berubah!)."),
    ("clickhouse order pk skip", "`ORDER BY (tarikh, id)` primary key isihan (bukan indeks B-tree!); `PARTITION BY toYYYYMM` buang; `TTL` gerak sejuk; Skip indexes (`bloom_filter/minmax`) — susunan sisihan (prune!), TTL kitaran (panas→sejuk!), `FINAL` elak (gabung latar!)."),
    ("duckdb parquet hive read", "`SELECT * FROM 's3://b/*.parquet'` query langsung (tiada server!); hive partitioning auto-dikesan; `COPY TO 'out.parquet'` eksport; MotherDuck kongsi (`ATTACH`) — analitik setempat (laptop berkuasa!), S3 sebagai tablespace (tiada ETL!)."),
    ("sqlite fts5 trigram", "`CREATE VIRTUAL TABLE ft USING fts5(tajuk, isi)` + `MATCH 'kopi*'` prefix + `highlight()` snippet + `rank` susun; trigram tokenizer CJK — carian terbenam (tiada pelayan!), tokenizer ikut bahasa (ngram CJK!), vakum berkala."),
    ("sqlite json generated", "`data->>'$.emel'` ekstrak + generated column berindeks untuk panas (`ADD COLUMN emel GENERATED ALWAYS AS (...) STORED`); `json_each` unnest; `json_patch` gabung — JSON fleksibel (tepi!), lajur nyata untuk disoal (indeks!)."),
    ("sqlite upsert vacuum", "`INSERT ... ON CONFLICT(email) DO UPDATE SET nama=excluded.nama` upsert atom; `VACUUM INTO 'sandaran.db'` sandaran dalam talian (tidak kunci lama!); WAL mode konkurensi — upsert tanpa lumba (satu kenyataan!), vakum berkala (bukan auto!)."),
    ("cockroach follower reads", "`AS OF SYSTEM TIME follower_read_timestamp()` baca replika (stale dibenarkan, pantas!); `ZONE CONFIG` pin/macau; `BACKUP SCHEDULED` — baca pengikut untuk analitik (bukan transaksi!), zon kawal latensi/kos."),
    ("timescale hypertable policy", "`create_hypertable('metrik','masa')` auto-partition masa (chunk ~25% RAM!); compression + retention policies (`add_retention_policy('30 hari')`); continuous aggregates prakira — siri-masa tanpa pembedahan partition manual (dasar dijadual!)."),
    ("kafka jdbc sink flatten", "JDBC Sink (`insert.mode=upsert`, `pk.mode=record_value`) tenggelamkan topik ke jadual (SMT `Flatten`/`ReplaceField` bentuk!); dead-letter `.errors` — tenggelam diisytihar (skema dipetakan!), ralat disalurkan (bukan digugurkan senyap!)."),
    ("flink sql window watarmark", "`TUMBLE(ts, INTERVAL '1' MINUTE)` + `WATERMARK FOR ts AS ts - INTERVAL '5' SECOND` tangani lewat (side-output terlalu-lewat!); `MATCH_RECOGNIZE` corak peristiwa — watermark takrif 'tepat masa' (lewat disalurkan!), tetingkap pilih semantik (tumbling vs hop vs session!)."),
    ("spark catalyst tungsten", "Catalyst mengoptimum (predicate pushdown! join order!), Tungsten laksana (whole-stage codegen!); `CACHE` panas guna-semula; `AQE` adaptif runtime — rancangan dibaca (`EXPLAIN`!), cache disengajakan (bukan harapan!), condong ditangani (salt keys!)."),
    ("athena projection partition", "`projection.tarikh.type=date` + `storage.location.template` ramal partition tanpa MSCK (serverless discovery!); `require_partition_filter` selamatkan kos; Parquet+Snappy — unjuran elak baiki manual (skala!), saring partition (imbasan penuh = bil!), mampat betul."),
    ("redshift distkey sortkey", "`DISTKEY(pelanggan_id)` sebaris join (collocated!), `SORTKEY(tarikh)` julat prune; `DISTSTYLE ALL` dimensi kecil salin; `VACUUM DELETE ONLY` pulih — kunci sebar ikut join (condong diukur!), isih ikut turas (prune!), vakum dijadual."),
    ("dynamodb single table gsi", "Satu jadual + `PK/SK` overload (pola akses direka dahulu!) + GSI jarang (`sparse` jimat!) + `TransactWriteItems` atom; `Query` (bukan `Scan`!) — corak akses direka (bukan dinormalkan!), GSI bayar per tulis (sedikit, disengajakan!)."),
    ("cassandra partition cluster", "Partition key sebaris (hotspot dibunuh!), clustering order dalam-partition; `ALLOW FILTERING` larangan prod; `tombstone` padam akhirnya (compaction!); quorum `LOCAL_QUORUM` — kunci partition direka (cardinality tinggi!), tombstone dipantau (baca perlahan!)."),
]



PHRASING_SQL = [
    "{q}",
    "{q} — tunjukkan SQL.",
    "Tulis query: {q}.",
    "Beri SQL untuk: {q}.",
    "Jawab dengan SQL: {q}.",
    "Tunjukkan cara dalam SQL: {q}.",
    "Apakah SQL bagi: {q}?",
    "Tuliskan ayat SQL: {q}.",
    "Lengkapkan SQL ini: {q}.",
    "Terangkan SQL ini dalam satu minit: {q}.",
    "Bilakah masa yang sesuai untuk SQL ini: {q}?",
    "Apakah fungsi query ini: {q}?",
    "Beri contoh sebenar query ini: {q}.",
]


def gen_docker():
    out = []
    for cmd, expl in DOCKER_FLAGS + DOCKER_DOCS + DOCKER_GAPS + DOCKER_ROUND6 + [(f"compose {f}", e) for f, e in COMPOSE_FIELDS]:
        for p in PHRASINGS:
            out.append((p.format(c=cmd), expl))
    return out


def gen_sql():
    out = []
    for t, cols in SQL_TABLES.items():
        c, c2 = cols[1], cols[2]
        cols_s, vals_s, setc = SQL_VALS[t]
        for task, sql in SQL_TASKS:
            q = task.format(t=t, c=c, c2=c2, v="'Ali'", cols=cols_s, vals=vals_s,
                            setc=setc)
            s = sql.format(t=t, c=c, c2=c2, v="'Ali'", cols=cols_s, vals=vals_s,
                           setc=setc)
            for p in PHRASING_SQL:
                out.append((p.format(q=q), f"```sql\n{s}\n```"))
    # join drills across tables
    joins = [
        ("Sertai pesanan dengan nama pengguna",
         "SELECT o.id, p.nama FROM pesanan o JOIN pengguna p ON p.id = o.pengguna_id;"),
        ("Sertai produk dengan baki stok rendah",
         "SELECT nama, stok FROM produk WHERE stok < 10 ORDER BY stok;"),
        ("Jumlah belanja setiap pengguna",
         "SELECT p.nama, SUM(o.jumlah) AS jumlah FROM pengguna p JOIN pesanan o ON o.pengguna_id = p.id GROUP BY p.nama;"),
    ]
    for q, s in joins:
        for p in PHRASING_SQL:
            out.append((p.format(q=q), f"```sql\n{s}\n```"))
    for q, a in SQL_CONCEPTS + SQL_ADV:
        out.append((q, a))
    return out


GENERATORS = {"docker": gen_docker, "sql": gen_sql}


