    ("alias sync fetch rebase", "`sync = !git fetch --prune && git rebase origin/$(git-main)` updates (one command!); `git-main` detects main/master — synced one-shot (fetch+rebase!), pruned (stale gone!), mains detected (both names!)."),
    ("alias cleanup merged branches", "`cleanup = !git branch --merged | grep -v main | xargs git branch -d` prunes landed (safe deletes!); `gone` handles remotes — merged pruned (clutter gone!), safe deletes (unmerged kept!), gone synced (upstream!)."),
